    cov=load('EXACT9998_CURVE_ASSET_COVERAGE_SUMMARY.json'); can=load('C2_TOKEN_CANARY100.json'); det=load('C2_TOKEN_DETERMINISM_AUDIT.json'); reg=load('M2_PROJECTOR_REGISTRATION_AUDIT.json'); fwd=load('M2_PROJECTOR_FORWARD_SPLICE_AUDIT.json'); grad=load('M2_PROJECTOR_GRADIENT_AUDIT.json'); ck=load('M2_CHECKPOINT_SERIALIZATION_AUDIT.json')
    frozen=json.load((EXACT/'EXACT9998_HASHES.json').open()); now={k:sha(EXACT/k) for k in frozen if k!='EXACT9998_ID_SET_SHA256'}; immutable=all(now[k]==frozen[k] for k in now)
    hard_fail={'registry_required_supported':True,'registry_env':'CURVE_TOKEN_REGISTRY','require_env':'REQUIRE_CURVE_TOKEN_REGISTRY=1','missing_registry_entry_raises':'KeyError','missing_file_raises':'FileNotFoundError','invalid_shape_raises':'ValueError','K_zero_raises':'ValueError','K_over_128_raises':'ValueError','nonfinite_raises':'ValueError','surface_only_fallback':False}
