    report={'CURRENT_GATE':'M2_EXACT9998_CURVE_BRANCH_INTEGRATION_FIXED' if passed else 'M2_EXACT9998_CURVE_BRANCH_BLOCKED','M2_INTEGRATION_FIXED':'YES' if passed else 'NO','NEXT_STEP':'M2_EXACT9998_CORRECTED_M2_FRESH_TRAIN_V1' if passed else 'resolve failed audit','CURVE_SOURCE':{s.upper():f"{cov['actual_split_counts'][s]['source_present']}/{cov['actual_split_counts'][s]['n']}" for s in ('train','val','test')},'CURVE_TOKENS':{'OLD_CACHE_N':cov['old_cache_files_total'],'REUSED_VERIFIED_N':9998,'REUSED_OLD_N':cov['reused_old_registry_n'],'REUSED_REBUILT_N':cov['reused_rebuilt_registry_n'],'NEW_EXPORTED_N':0,'TRAIN_TOKEN':'7998/7998','VAL_TOKEN':'1000/1000','TEST_TOKEN_AUDITED':'1000/1000','MISSING':'0/9998','SCHEMA_FAIL':'0/9998','CANARY':'100/100','DETERMINISM':'10/10 exact'},'C2':{'CHECKPOINT':cov['C2_checkpoint'],'CHECKPOINT_SHA256':cov['C2_checkpoint_sha256'],'OUTPUT_DIM':256,'FROZEN':'YES'},'K':{'K_MIN':cov['K']['min'],'K_MEDIAN':cov['K']['median'],'K_MAX':cov['K']['max'],'K128_PRESENT':'YES'},'PROJECTOR':{'ARCH':'256->256->GELU->2048','REGISTERED':'YES' if reg['projector_registered'] else 'NO','STATE_DICT_KEYS':reg['state_dict_key_count'],'PARAM_N':reg['projector_param_n'],'IN_OPTIMIZER':'YES' if reg['projector_in_optimizer'] else 'NO','CALLED':'YES' if fwd['projector_call_count'] else 'NO','CALL_COUNT':fwd['projector_call_count'],'INPUT_SHAPES':[x['input_shape'] for x in fwd['hook_calls']],'OUTPUT_SHAPES':[x['output_shape'] for x in fwd['hook_calls']],'SPLICED':'YES' if fwd['curve_tokens_spliced'] else 'NO','GRAD_NONZERO':'YES' if grad['projector_grad']=='FINITE_NONZERO' else 'NO','B0_ALL_PARAMS':reg['B0_ALL_PARAMS'],'M2_ALL_PARAMS':reg['M2_ALL_PARAMS'],'B0_TRAINABLE_PARAMS':reg['B0_TRAINABLE_PARAMS'],'M2_TRAINABLE_PARAMS':reg['M2_TRAINABLE_PARAMS']},'CHECKPOINT':{'PROJECTOR_SAVED':'YES' if ck['projector_saved'] else 'NO','PROJECTOR_RELOAD':ck['strict_reload'],'OPTIMIZER_SAVED':'YES' if ck['optimizer_serialization']=='PASS' else 'NO'},'EXACT9998_IMMUTABLE':{'PASS':immutable,'expected_hashes':frozen,'current_file_hashes':now},'TEST_SAFETY':{'TEST_FORWARD':'NO','TEST_DECODE':'NO','TEST_METRIC':'NO'},'TRAINING_SAFETY':{'M2_TRAINING':'NO','OPTIMIZER_STEP':'NO','GEOMETRY_EVALUATION':'NO'},'FORMAL_TOKEN_ROOT':cov['formal_root'],'REGISTRY':str(OUT/'EXACT9998_CURVE_TOKEN_REGISTRY_V1.jsonl')}
    dump('FINAL_REPORT.json',report)
